#!/usr/bin/env python3
"""Anchored transform: final consolidation of manual merges
(fusao-final design) over goanime-mobile main
10e051179a25ea3efb35add0d2f1e591863fb38a.

Fails closed: every hunk's old text must occur exactly once in the
target file, and new files must not already exist.
Usage: python3 goanime-union-apply.py [checkout dir] (default ".")
"""
import base64
import json
import pathlib
import sys

PLAN = json.loads(base64.b64decode(r'''''').decode('utf-8'))


def main():
    root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else ".")
    for rel, hs in PLAN['files'].items():
        path = root / rel
        text = path.read_text()
        for i, h in enumerate(hs):
            count = text.count(h['old'])
            if count != 1:
                print(f'FAIL {rel} hunk {i}: anchor occurs {count}x')
                sys.exit(1)
            text = text.replace(h['old'], h['new'])
        path.write_text(text)
        print(f'OK {rel}: {len(hs)} hunks')
    for rel, content in PLAN['new_files'].items():
        path = root / rel
        if path.exists():
            print(f'FAIL {rel}: already exists')
            sys.exit(1)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content)
        print(f'OK {rel}: new file')


if __name__ == '__main__':
    main()
